/**
 * The vendored engine and data are Agent_Loop_Sim's files at the pinned commit, byte for byte;
 * the vendored port reproduces the engine's own policy fixtures; and the site's fixtures were
 * generated by the Python reference at that same commit.
 */
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

import VENDORED from "@/lib/engine/vendor/VENDORED.json";

const ROOT = join(__dirname, "../..");
const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");
type Obj = Record<string, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
const norm = (x: unknown) => JSON.parse(JSON.stringify(x));

describe("vendored engine", () => {
  it("every file matches the SHA-256 recorded with its commit", () => {
    const files = Object.entries(VENDORED.files);
    expect(files.length).toBe(15);
    expect(VENDORED.commit).toMatch(/^[0-9a-f]{40}$/);
    for (const [path, rec] of files)
      expect(sha(readFileSync(join(ROOT, path))), path).toBe(rec.sha256);
  });

  it("vendors the TS port with its policy module, its fixtures and recorded results", () => {
    const froms = Object.values(VENDORED.files).map((f) => f.from);
    for (const f of [
      "ts/src/policy/labels.ts",
      "ts/src/policy/catalogue.ts",
      "ts/src/policy/engine.ts",
      "ts/src/policy/capabilities.ts",
      "ts/src/policy/sandbox.ts",
      "ts/src/policy/depth.ts",
      "ts/src/policy/study.ts",
      "ts/src/policy/index.ts",
      "ts/src/policy_data.json",
      "ts/src/rng.ts",
      "fixtures/policy_fixtures.json",
      "fixtures/policy_results.md",
    ])
      expect(froms).toContain(f);
  });

  it("the engine's policy fixtures are reproduced by the vendored port", async () => {
    const { P } = await import("@/lib/engine");
    const fx = JSON.parse(
      readFileSync(join(ROOT, "tests/fixtures/policy_fixtures.json"), "utf8"),
    ) as Obj;
    expect(fx.engine).toBe("1.10.0");
    for (const r of fx.lattice as Obj[]) {
      expect(P.labels.join(r.a, r.b)).toEqual(r.join);
      expect(P.labels.leq(r.a, r.b)).toBe(r.leq);
    }
    const S = P.study;
    expect(norm(S.trifectaStudy())).toEqual(fx.study.trifecta);
    expect(norm(S.privilegeStudy())).toEqual(fx.study.privilege);
    expect(norm(S.sandboxFrames())).toEqual(fx.study.sandbox);
    expect(norm(S.allLayerSets())).toEqual(fx.sandbox);
    expect(norm(S.depthStudy())).toEqual(fx.study.depth);
    for (const p of P.catalogue.PLAN_ORDER)
      expect(norm(S.contextFrames(p))).toEqual(fx.study.context[p]);
  });

  it("the site's fixtures come from the same commit", () => {
    const fx = JSON.parse(
      readFileSync(join(ROOT, "tests/fixtures/site_fixtures.json"), "utf8"),
    ) as { commit: string };
    expect(fx.commit).toBe(VENDORED.commit);
  });
});
